actions.script:
def activeOrg=ec.user.getPreference('ACTIVE_ORGANIZATION')
def list=priceListId ? ec.entity.find('zenith.erp.pricing.PriceList').condition('priceListId',priceListId).disableAuthz().one() : null
allowed=list != null && (ec.user.isInGroup('ADMIN') || (activeOrg && activeOrg != '_NA_' && list.organizationPartyId==activeOrg))
if(!allowed) ec.message.addError("You do not have access to this price list.")

if.script:
def self = priceListId?.toString()
def parent = parentPriceListId.toString().trim()
if (parent == self) {
    valid = false
    ec.message.addError("A price list cannot be its own fallback price list.")
} else {
    def parentRow = ec.entity.find("zenith.erp.pricing.PriceList").condition("priceListId", parent).disableAuthz().one()
    if (parentRow == null) {
        valid = false
        ec.message.addError("The selected fallback price list does not exist.")
    } else {
        // Same-org check. Owner org = the one passed in (create), else the edited list's own org.
        def ownerOrg = organizationPartyId
        if (!ownerOrg && self) {
            ownerOrg = ec.entity.find("zenith.erp.pricing.PriceList").condition("priceListId", self).disableAuthz().one()?.organizationPartyId
        }
        if (ownerOrg && parentRow.organizationPartyId != ownerOrg) {
            valid = false
            ec.message.addError("The fallback price list must belong to the same organization.")
        } else if (self) {
            // Cycle: walk the proposed parent's chain; if it returns to this list it loops.
            // The visited-set makes the walk terminate even if the stored data already cycles.
            def seen = new HashSet()
            def cur = parent
            while (cur && !seen.contains(cur)) {
                if (cur == self) {
                    valid = false
                    ec.message.addError("This fallback would create a loop in the price-list chain.")
                    break
                }
                seen.add(cur)
                cur = ec.entity.find("zenith.erp.pricing.PriceList").condition("priceListId", cur).disableAuthz().one()?.parentPriceListId
            }
        }
    }
}

actions.script:
def _isDiscount = priceTypeEnumId == 'PtpDiscount'
def _dpBlank = (discountPercent == null || !discountPercent.toString().trim())
if (!_dpBlank && ((discountPercent as BigDecimal) < 0 || (discountPercent as BigDecimal) > 100))
    ec.message.addError("Discount % must be between 0 and 100.")
// ZE-PRC-009 (PRC-038): reject a negative Unit Price (0 is allowed for a free item). Guards both the
// Add-Item form and the bulk import#PriceListItems, which is the only other caller of this service.
if (unitPrice != null && (unitPrice as BigDecimal) < 0)
    ec.message.addError("Unit Price cannot be negative.")
if (_isDiscount) {
    if (_dpBlank) ec.message.addError("Enter a Discount % for a Discount-type price item.")
    if (unitPrice == null) unitPrice = BigDecimal.ZERO
} else if (unitPrice == null) {
    ec.message.addError("Enter a Unit Price for a Fixed-type price item.")
}

// The import reports partial success: isolate each row's rollback and count only a committed result.
items.each { item ->
    ec.message.pushErrors()
    try {
        def result=ec.service.sync().name('zenith.pricing.PricingServices.set#PriceListItem')
            .parameters([priceListId:priceListId,productId:item.productId,unitPrice:item.unitPrice,
                minQuantity:item.minQuantity != null ? item.minQuantity : 1,
                maxQuantity:item.maxQuantity,changeReason:changeReason])
            .requireNewTransaction(true).call()
        if(!ec.message.hasError() && result?.priceListItemId) importedCount++
        else errorCount++
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}

iterate.script:
def op = (cond.operator ?: 'equals').toString().trim()
if (!op) op = 'equals'
def fv = cond.fieldValue
def fvTo = cond.fieldValueTo
def t = cond.conditionTypeEnumId

def csvList = { s -> (s ?: '').toString().split(',').collect { it.trim() }.findAll { it } }
// Invalid legacy operators and incomplete lists must not broaden a rule's scope.
def catMatch = { actual ->
    if (!(op in ['equals','not-equals','in']) || !fv?.toString()?.trim()) return false
    if (op=='in' && fv.toString().split(',',-1).any {!it.trim()}) return false
    def a = (actual == null) ? null : actual.toString()
    def f = (fv == null) ? null : fv.toString()
    if (op == 'not-equals') return a != f
    if (op == 'in') return csvList(fv).contains(a)
    return a == f
}
// numeric compare for the Minimum types: default/equals -> '>=' (preserves the type),
// plus greater-than / less-than / not-equals / between / in
def numMatch = { lv ->
    if (lv == null) return false
    try {
        if (!(op in ['equals','not-equals','greater-than','less-than','between','in'])) return false
        if (op == 'in') {
            if (!fv || fv.toString().split(',',-1).any {!it.trim()}) return false
            def numbers=csvList(fv).collect {it as BigDecimal}
            return numbers && numbers.every {it>=0} && numbers.any {lv==it}
        }
        def bd = (fv as BigDecimal)
        if (bd<0 || (op=='between' && ((fvTo as BigDecimal)<bd))) return false
        if (op == 'greater-than') return lv > bd
        if (op == 'less-than')    return lv < bd
        if (op == 'not-equals')   return lv != bd
        if (op == 'between')      return lv >= bd && lv <= (fvTo as BigDecimal)
        return lv >= bd
    } catch (Exception e) { return false }
}

boolean match
if (t == 'PctProduct') {
    match = catMatch(productId)
} else if (t == 'PctChannel') {
    match = catMatch(salesChannelEnumId)
} else if (t == 'PctCustomerGroup') {
    match = catMatch(customerGroupId)
} else if (t == 'PctRegion') {
    match = catMatch(regionGeoId)
} else if (t == 'PctProductCategory') {
    def cats = (op == 'in') ? csvList(fv) : [ (fv == null ? null : fv.toString()) ]
    boolean isMember = false
    for (cat in cats) {
        if (!cat) continue
        def cm = ec.entity.find('mantle.product.category.ProductCategoryMember')
                   .condition('productId', productId).condition('productCategoryId', cat)
                   .conditionDate('fromDate', 'thruDate', now).list()
        if (cm) { isMember = true; break }
    }
    def validCategory=op in ['equals','not-equals','in'] && fv?.toString()?.trim() && (op!='in' || !fv.toString().split(',',-1).any {!it.trim()})
    match = validCategory && ((op == 'not-equals') ? !isMember : isMember)
} else if (t == 'PctMinQuantity') {
    match = numMatch(quantity == null ? null : (quantity as BigDecimal))
} else if (t == 'PctMinAmount') {
    match = (unitPrice == null || quantity == null) ? false : numMatch((unitPrice as BigDecimal) * (quantity as BigDecimal))
} else if (t == 'PctDayOfWeek') {
    def zone=ec.user.getTimeZone().toZoneId()
    def day=java.time.Instant.ofEpochMilli(((java.util.Date)now).time).atZone(zone).getDayOfWeek()
    def name=day.name(), abbreviation=name.substring(0,3), number=day.value.toString()
    def days=csvList(fv).collect {it.toUpperCase(java.util.Locale.ROOT)}
    def legalDays=['MON','TUE','WED','THU','FRI','SAT','SUN','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY','SUNDAY','1','2','3','4','5','6','7']
    def includes=days.any {it in [name,abbreviation,number]}
    match=days && days.every {it in legalDays} && (op=='not-equals' ? !includes : op in ['equals','in'] && includes)
} else if (t == 'PctTimeRange') {
    match=false
    try {
        def parts=(fv ?: '').toString().split('-',-1)
        if(parts.length==2 && op in ['equals','not-equals']) {
            def zone=ec.user.getTimeZone().toZoneId()
            def time=java.time.Instant.ofEpochMilli(((java.util.Date)now).time).atZone(zone).toLocalTime()
            def start=java.time.LocalTime.parse(parts[0].trim()), end=java.time.LocalTime.parse(parts[1].trim())
            def inside=start.isAfter(end) ? !time.isBefore(start) || !time.isAfter(end) : !time.isBefore(start) && !time.isAfter(end)
            match=op=='not-equals' ? !inside : inside
        }
    } catch(Exception ignored) {match=false}
} else {
    match = false
}
if (!match) allMatch = false
